<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
$role=(string)($_SESSION['role']??'');$uid=(int)($_SESSION['user_id']??0);
if($role==='headteacher'){header('Location: school_setup.php');exit;}
if(!in_array($role,['system_admin','sub_admin'],true)){header('Location: notes.php');exit;}
$db=db();$error='';$saved=isset($_GET['saved']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');$name=trim((string)($_POST['name']??''));$classId=(int)($_POST['class_id']??0);
 try{
  if($name===''||mb_strlen($name)>100)throw new DomainException('Enter a name within 100 characters.');
  $db->beginTransaction();
  if($action==='add_class'){
   if(mb_strlen($name)>80)throw new DomainException('Class names must be 80 characters or fewer.');
   $q=$db->prepare('INSERT INTO academic_classes(name,created_by) VALUES(?,?)');$q->execute([$name,$uid]);$entityId=(int)$db->lastInsertId();$entity='academic_class';
  }elseif($action==='add_subject'){
   if($role!=='system_admin')throw new DomainException('Only system admins can add core subjects.');
   $q=$db->prepare('SELECT id FROM academic_classes WHERE id=?');$q->execute([$classId]);if(!$q->fetchColumn())throw new DomainException('Choose a valid class.');
   $q=$db->prepare('INSERT INTO academic_class_subjects(class_id,name,created_by) VALUES(?,?,?)');$q->execute([$classId,$name,$uid]);$entityId=(int)$db->lastInsertId();$entity='academic_subject';
  }else throw new DomainException('Choose a valid catalog action.');
  $q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'create',$entity,$entityId,json_encode(['name'=>$name,'class_id'=>$classId?:null],JSON_THROW_ON_ERROR)]);$db->commit();header('Location: academics.php?saved=1');exit;
 }catch(DomainException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(PDOException $e){if($db->inTransaction())$db->rollBack();$error=$e->getCode()==='23000'?'That class or subject already exists.':'The catalog item could not be saved.';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error='The catalog item could not be saved.';}
}
$classes=$db->query('SELECT c.id,c.name,COUNT(s.id) subject_count FROM academic_classes c LEFT JOIN academic_class_subjects s ON s.class_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$subjects=[];$q=$db->query('SELECT id,class_id,name FROM academic_class_subjects ORDER BY name');foreach($q->fetchAll() as $row)$subjects[(int)$row['class_id']][]=$row;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Academics · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav"><a class="nav-item" href="index.php">⌂ Overview</a><a class="nav-item active" href="academics.php">▤ Academics</a><?php if(can_access_school_setup()):?><a class="nav-item" href="school_setup.php"><span class="nav-icon" aria-hidden="true">⚙</span>School setup</a><?php endif;?><a class="nav-item" href="schools.php">▦ Schools</a></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ Sign out</a></div></aside><main class="main-area"><header class="topbar"><div class="crumb">Workspace / Academics</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><span class="user-name"><?=e($_SESSION['name']??'')?></span></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">ACADEMIC STRUCTURE</div><h1>Academics</h1><p class="muted">Define the standard classes and core subjects available to schools. Schools can display their own local names.</p></div></section><?php if($saved):?><div class="notice success">Catalog updated.</div><?php endif;?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><section class="note-create"><h2>Add a system class</h2><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_class"><label for="class-name">Class name</label><input id="class-name" name="name" maxlength="80" placeholder="e.g. Grade 1" required><button class="button primary">Add class</button></form></section><section class="content-section"><h2>Classes and core subjects</h2><?php if(!$classes):?><div class="empty-state"><h3>No system classes yet</h3><p>Add a class above before schools can set up their academic structure.</p></div><?php endif;?><?php foreach($classes as $class):?><details class="class-directory-accordion"><summary><?=e($class['name'])?> <span class="count-pill"><?= (int)$class['subject_count']?> core subjects</span></summary><div class="class-directory-content"><?php foreach($subjects[(int)$class['id']]??[] as $subject):?><span class="assignment-chip"><?=e($subject['name'])?></span><?php endforeach;?><?php if($role==='system_admin'):?><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_subject"><input type="hidden" name="class_id" value="<?=$class['id']?>"><label>Add core subject to <?=e($class['name'])?></label><input name="name" maxlength="100" required placeholder="e.g. Mathematics"><button class="button primary">Add subject</button></form><?php endif;?></div></details><?php endforeach;?></section></div></main></div></body></html>